Method.Source:
    /// <summary>
    /// Temporary fix to allow updating status to enabled through data entity.
    /// Previous code returns false here has the data entity field is already set to 'Enabled'
    /// </summary>
    /// <returns>true if the record can be updated; otherwise, false.</returns>
    public boolean allowEdit()
    {
        boolean ret = next allowEdit();

        return (ret || this.orig().Status == GUPDisabledEnabled::Disabled);
    }
